const DB={players:[],maps:[],matches:[],aliases:{}};
const BASE={players:[],maps:[],matches:[],aliases:{}};
const state={tab:'home',logged:false,selected:['gletcher'],focused:null,metric:'kd',map:'all',playerSearch:'',teamA:[],teamB:[],compare:['gletcher','donater'],detailPlayer:null,whatIfOut:'',whatIfIn:'',teamChange:null,recordFilter:'career',recordMetric:'kills',recordMap:'all',baseMode:'maps',showArchived:false,mapPlayer:'all',hydrationError:null,storageWarning:null,bootError:null,serverSync:false,serverVersion:null,serverBusy:false,cloudMode:false,cloudAdmin:false};
let SERVER_AUDIT=[]; let SERVER_EVENT_SOURCE=null; let SERVER_REFRESH_TIMER=null;
const $=s=>document.querySelector(s);
function toast(message){let box=document.getElementById('toast');if(!box){box=document.createElement('div');box.id='toast';box.className='toast';document.body.appendChild(box)}box.textContent=String(message||'');box.classList.add('show');clearTimeout(window.__cs5ToastTimer);window.__cs5ToastTimer=setTimeout(()=>box.classList.remove('show'),2600)}
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const fmt=(x,n=2)=>Number.isFinite(x)?x.toFixed(n):'—';
const metricLabels={kd:'K/D',diff:'K-D',kills:'K',deaths:'D',assists:'A',impact:'Импакт',index:'Индекс игрока',form:'Форма',stability:'Стабильность'};
const mapKey=name=>String(name||'').trim().toLowerCase();
const mapAsset=name=>`assets/maps/${encodeURIComponent(mapKey(name))}.svg`;
const mapRemoteAsset=name=>`https://raw.githubusercontent.com/ghostcap-gaming/cs2-map-images/main/cs2/de_${encodeURIComponent(mapKey(name))}.png`;
const mapIconRemoteAsset=name=>`https://raw.githubusercontent.com/MurkyYT/cs2-map-icons/main/images/de_${encodeURIComponent(mapKey(name))}.png`;
const mapBg=name=>`linear-gradient(180deg,rgba(3,9,16,.04),rgba(3,9,16,.72)),url('${mapAsset(name)}')`;
const trendMarkup=(value,label='')=>{const n=Number(value);if(!Number.isFinite(n))return `<em class="trend-flat">— ${esc(label)}</em>`;const up=n>=0;return `<em class="${up?'trend-up':'trend-down'}">${up?'↑':'↓'} ${fmt(Math.abs(n),1)}${label?` ${esc(label)}`:''}</em>`};
const mapThumb=(name,size='')=>`<div class="map-thumb ${size}" style="background-image:${mapBg(name)}"><span>${esc(name||'CS2')}</span></div>`;

async function loadData(name){const embedded=window.CS5_EMBEDDED_DATA?.[name];if(embedded)return embedded;try{const r=await fetch('data/'+name+'.json',{cache:'no-store'});if(!r.ok)throw Error(`data/${name}.json: HTTP ${r.status}`);return r.json()}catch(e){throw e}}
async function loadServerState(){if(window.CS2Cloud?.configured){try{return await CS2Cloud.load()}catch(e){state.storageWarning='Облачная база пока недоступна: '+(e?.message||'ошибка подключения') ;return null}}if(location.protocol!=='http:'&&location.protocol!=='https:')return null;try{const r=await fetch('/api/state',{cache:'no-store'});if(!r.ok)return null;const x=await r.json();if(!validateBase(x))throw Error('Серверная база не прошла проверку');return x}catch{return null}}
function applyLoadedState(candidate,audit=[]){BASE.players=JSON.parse(JSON.stringify(candidate.players));BASE.maps=JSON.parse(JSON.stringify(candidate.maps));BASE.matches=JSON.parse(JSON.stringify(candidate.matches));BASE.aliases=JSON.parse(JSON.stringify(candidate.aliases));DB.players=JSON.parse(JSON.stringify(candidate.players));DB.maps=JSON.parse(JSON.stringify(candidate.maps));DB.matches=JSON.parse(JSON.stringify(candidate.matches));DB.aliases=JSON.parse(JSON.stringify(candidate.aliases));SERVER_AUDIT=Array.isArray(candidate.audit)?JSON.parse(JSON.stringify(candidate.audit)):Array.isArray(audit)?JSON.parse(JSON.stringify(audit)):[];normalizeState();}
async function load(){
  try{
    const embedded=window.CS5_EMBEDDED_DATA||{};
    let candidate=(Array.isArray(embedded.players)&&Array.isArray(embedded.maps)&&Array.isArray(embedded.matches)&&embedded.aliases&&typeof embedded.aliases==='object')
      ? {players:embedded.players,maps:embedded.maps,matches:embedded.matches,aliases:embedded.aliases}
      : null;
    if(!candidate){
      const [p,m,ma,a]=await Promise.all(['players','maps','matches','aliases'].map(loadData));
      candidate={players:p.players,maps:m.maps,matches:ma.matches,aliases:a.aliases};
    }
    let ov=null;
    try{ov=JSON.parse(localStorage.getItem('cs5_base_override')||'null')}catch{ov=null}
    if(!window.CS2Cloud?.configured&&ov&&Array.isArray(ov.players)&&Array.isArray(ov.maps)&&Array.isArray(ov.matches)&&ov.aliases&&typeof ov.aliases==='object')candidate=ov;
    if(!validateBase(candidate))throw Error('База не прошла проверку');
    applyLoadedState(candidate);
    hydrate();
    if(!validateBase(DB))throw Error('Локальные изменения повредили базу');

    state.cloudMode=!!window.CS2Cloud?.configured;
    state.serverSync=state.cloudMode;
    render();

    if(state.hydrationError)toast(state.hydrationError);
    else if(state.storageWarning)toast(state.storageWarning);

    if(!state.cloudMode)return;

    // Cloud data/auth refresh runs after the first paint, so the dashboard is usable immediately.
    const remote=await loadServerState();
    if(remote){
      state.serverSync=true;
      state.serverVersion=remote.updated_at||null;
      applyLoadedState(remote,remote.audit);
      try{state.cloudAdmin=await CS2Cloud.isAdmin();state.logged=state.cloudAdmin}catch{state.cloudAdmin=false;state.logged=false}
      render();
      connectServerEvents();
    }else{
      // Keep cloud mode enabled so login/commit still use Supabase if the initial read is temporarily slow.
      state.serverSync=true;
      state.cloudAdmin=false;
      state.logged=false;
      if(state.storageWarning)toast(state.storageWarning);
    }
  }catch(e){
    state.bootError=e?.message||'Не удалось загрузить базу';
    const v=$('#view');
    if(v)v.innerHTML=`<section class="section"><div class="panel card"><div class="eyebrow">SYSTEM ERROR</div><h2>База не загружена</h2><div class="notice">${esc(state.bootError)}</div><div class="footer-note">Проверь наличие папки data рядом с index.html. Данные не были изменены.</div><button class="btn primary" onclick="location.reload()">ПОВТОРИТЬ</button></div></section>`;
  }
}
async function refreshFromServer(silent=false){if(!state.serverSync)return false;try{const x=window.CS2Cloud?.configured?await CS2Cloud.load():await (async()=>{const r=await fetch('/api/state',{cache:'no-store'});if(!r.ok)throw Error('server unavailable');return r.json()})();if(!validateBase(x))throw Error('invalid server state');applyLoadedState(x,x.audit);state.serverVersion=x.updated_at||null;render();if(!silent)toast('Данные синхронизированы');return true}catch(e){if(!silent)toast('Не удалось синхронизировать данные');return false}}
function connectServerEvents(){if(!state.serverSync||SERVER_EVENT_SOURCE)return;if(window.CS2Cloud?.configured){CS2Cloud.subscribe(()=>refreshFromServer(true));return}try{SERVER_EVENT_SOURCE=new EventSource('/api/events');SERVER_EVENT_SOURCE.addEventListener('update',()=>refreshFromServer(true));SERVER_EVENT_SOURCE.onerror=()=>{if(SERVER_REFRESH_TIMER)return;SERVER_REFRESH_TIMER=setInterval(()=>refreshFromServer(true),3000)}}catch{SERVER_REFRESH_TIMER=setInterval(()=>refreshFromServer(true),3000)}}
function hydrate(){let additions=[];try{additions=window.__cs5HydrateAdditions||null}catch{additions=null}if(!Array.isArray(additions)){additions=[];try{const raw=localStorage.getItem('cs5_additions');if(raw){const parsed=JSON.parse(raw);if(Array.isArray(parsed))additions=parsed;else state.storageWarning='Хранилище cs5_additions повреждено: ожидается массив. Используется безопасное пустое состояние.'}}catch{state.storageWarning='Хранилище cs5_additions повреждено: JSON не читается. Используется безопасное пустое состояние.'}}if(!additions.length)return;const snapshot=JSON.parse(JSON.stringify(DB));try{for(const x of additions){if(!x||typeof x!=='object')throw Error('invalid local operation');if(!['map','match','player','aliases','player_patch','match_patch','map_patch'].includes(x.kind))throw Error('unknown local operation');if(x.kind==='map'&&(!x.map||typeof x.map!=='object'))throw Error('map payload missing');if(x.kind==='match'&&(!x.match||typeof x.match!=='object'))throw Error('match payload missing');if(x.kind==='player'&&(!x.player||typeof x.player!=='object'))throw Error('player payload missing');if(x.kind==='aliases'&&(!x.aliases||typeof x.aliases!=='object'||Array.isArray(x.aliases)))throw Error('aliases payload missing');if(['player_patch','match_patch','map_patch'].includes(x.kind)&&(!x.patch||typeof x.patch!=='object'||Array.isArray(x.patch)))throw Error('patch payload missing');if(x.kind==='map'&&x.map)DB.maps.push(x.map);if(x.kind==='match'&&x.match)DB.matches.push(x.match);if(x.kind==='player'&&x.player)DB.players.push(x.player);if(x.kind==='aliases')Object.assign(DB.aliases,x.aliases||{});if(x.kind==='player_patch'){const p=DB.players.find(p=>p.player_id===x.player_id);if(!p)throw Error('player patch target missing');Object.assign(p,x.patch||{})}if(x.kind==='match_patch'){const m=DB.matches.find(m=>m.match_id===x.match_id);if(!m)throw Error('match patch target missing');Object.assign(m,x.patch||{})}if(x.kind==='map_patch'){const m=DB.maps.find(m=>m.map_id===x.map_id);if(!m)throw Error('map patch target missing');Object.assign(m,x.patch||{})}}if(!validateBase(DB))throw Error('invalid hydrated base')}catch{DB.players=snapshot.players;DB.maps=snapshot.maps;DB.matches=snapshot.matches;DB.aliases=snapshot.aliases;state.hydrationError='Локальные изменения не применены: обнаружена повреждённая или несовместимая запись. Исходная база сохранена.'}}
function validateBase(b){const r=window.CS2Validation?.validateBase?.(b);return !!r?.ok}
function activeMatches(){return DB.matches.filter(m=>m.archived!==true)}
function matchTime(m){const t=Date.parse(m?.played_at||m?.date||m?.created_at||'');return Number.isFinite(t)?t:0}
function latestMatch(list=activeMatches()){return list.slice().sort((a,b)=>matchTime(a)-matchTime(b)||String(a.match_id).localeCompare(String(b.match_id))).at(-1)||null}
function matchMaps(match){return (match?.map_ids||[]).map(id=>DB.maps.find(x=>x.map_id===id)).filter(Boolean).filter(x=>x.archived!==true)}
function latestDetailedMap(match){return matchMaps(match).filter(x=>x.stats_available).at(-1)||null}
function mapScoreText(m){return m?.score&&Number.isFinite(Number(m.score.team_a))&&Number.isFinite(Number(m.score.team_b))?`${m.score.team_a}:${m.score.team_b}`:'—'}
function safeJsonArray(key){try{const raw=localStorage.getItem(key);if(!raw)return[];const v=JSON.parse(raw);if(!Array.isArray(v)){state.storageWarning=`Хранилище ${key} повреждено: ожидается массив. Используется безопасное пустое состояние.`;return[]}return v}catch{state.storageWarning=`Хранилище ${key} повреждено: JSON не читается. Используется безопасное пустое состояние.`;return[]}}
function auditLog(){return state.serverSync?SERVER_AUDIT.slice():safeJsonArray('cs5_audit_log')}
function logAudit(action,target,detail={}){const entry={id:'audit_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),at:new Date().toISOString(),action,target,detail};if(state.serverSync){SERVER_AUDIT.push(entry);SERVER_AUDIT=SERVER_AUDIT.slice(-500);return}const log=auditLog();log.push(entry);localStorage.setItem('cs5_audit_log',JSON.stringify(log.slice(-500)))}
function additions(){return state.serverSync?[]:safeJsonArray('cs5_additions')}
function persistAdditions(a){if(state.serverSync){const xhr=new XMLHttpRequest();xhr.open('POST','/api/commit',false);xhr.setRequestHeader('Content-Type','application/json');xhr.send(JSON.stringify({operations:a.map((op,i)=>({...op,_sync_id:`${Date.now()}_${i}_${Math.random().toString(36).slice(2,8)}`}) )}));if(xhr.status<200||xhr.status>=300)throw Error('server commit failed');return}const next=JSON.stringify(a);const prev=localStorage.getItem('cs5_additions');try{localStorage.setItem('cs5_additions',next);if(localStorage.getItem('cs5_additions')!==next)throw Error('storage verification failed')}catch(e){try{if(prev===null)localStorage.removeItem('cs5_additions');else localStorage.setItem('cs5_additions',prev)}catch{};throw e}}
function persistChange(a,audit){if(state.serverSync){if(window.CS2Cloud?.configured){const entry=audit?{id:'audit_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),at:new Date().toISOString(),action:audit.action,target:audit.target,detail:audit.detail||{}}:null;state.serverBusy=true;CS2Cloud.commit(a,entry).then(data=>{state.serverBusy=false;state.serverVersion=data.updated_at||null;if(entry){SERVER_AUDIT.push(entry);SERVER_AUDIT=SERVER_AUDIT.slice(-500)}}).catch(e=>{state.serverBusy=false;toast('Облачное сохранение не удалось: '+(e?.message||'ошибка'));refreshFromServer(true)});return true}const ops=a.map((op,i)=>({...op,_sync_id:`${Date.now()}_${i}_${Math.random().toString(36).slice(2,8)}`}));const entry=audit?{id:'audit_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),at:new Date().toISOString(),action:audit.action,target:audit.target,detail:audit.detail||{}}:null;const xhr=new XMLHttpRequest();xhr.open('POST','/api/commit',false);xhr.setRequestHeader('Content-Type','application/json');xhr.send(JSON.stringify({operations:ops,audit:entry}));if(xhr.status<200||xhr.status>=300)throw Error('server commit failed');if(entry){SERVER_AUDIT.push(entry);SERVER_AUDIT=SERVER_AUDIT.slice(-500)}return true}const nextAdd=JSON.stringify(a);const prevAdd=localStorage.getItem('cs5_additions');const prevAudit=localStorage.getItem('cs5_audit_log');let nextAudit=prevAudit;if(audit){const log=auditLog();log.push({id:'audit_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),at:new Date().toISOString(),action:audit.action,target:audit.target,detail:audit.detail||{}});nextAudit=JSON.stringify(log.slice(-500))}try{localStorage.setItem('cs5_additions',nextAdd);if(audit)localStorage.setItem('cs5_audit_log',nextAudit);if(localStorage.getItem('cs5_additions')!==nextAdd|| (audit&&localStorage.getItem('cs5_audit_log')!==nextAudit))throw Error('storage verification failed')}catch(e){try{if(prevAdd===null)localStorage.removeItem('cs5_additions');else localStorage.setItem('cs5_additions',prevAdd);if(prevAudit===null)localStorage.removeItem('cs5_audit_log');else localStorage.setItem('cs5_audit_log',prevAudit)}catch{};throw e}}
function normalizeState(){const ids=new Set(activePlayers().map(p=>p.player_id));const allIds=new Set(DB.players.map(p=>p.player_id));state.selected=state.selected.filter(id=>ids.has(id));if(!state.selected.length&&activePlayers()[0])state.selected=[activePlayers()[0].player_id];state.teamA=[...new Set(state.teamA.filter(id=>allIds.has(id)))].slice(0,5);state.teamB=[...new Set(state.teamB.filter(id=>allIds.has(id)&&!state.teamA.includes(id)))].slice(0,5)}
function activePlayers(){return DB.players.filter(p=>p.is_active!==false)}
function player(id){return DB.players.find(p=>p.player_id===id)}
function playerName(id){return player(id)?.display_name||id}
function detailMapsFor(id){const activeIds=new Set(activeMatches().map(x=>x.match_id));return DB.maps.filter(m=>m.archived!==true&&activeIds.has(m.match_id)&&m.stats_available&&m.player_stats.some(s=>s.player_id===id))}
function playedMapsFor(id){let n=detailMapsFor(id).length;for(const ma of activeMatches().filter(x=>x.source_kind==='compact_bo3'))if((ma.series_aggregate_stats||[]).some(s=>s.player_id===id))n+=matchMaps(ma).length;return n}
function aggregate(id,rows=detailRows(id),includeCompact=true){let k=0,d=0,a=0;for(const r of rows){k+=r.kills;d+=r.deaths;a+=r.assists}if(includeCompact)for(const m of activeMatches().filter(x=>x.source_kind==='compact_bo3'))for(const s of(m.series_aggregate_stats||[]))if(s.player_id===id){k+=s.kills;d+=s.deaths;a+=s.assists}const maps=includeCompact?playedMapsFor(id):rows.length;return{maps,detailed:rows.length,k,d,a,kd:d?k/d:0,kdDiff:k-d,kpm:maps?k/maps:0,apm:maps?a/maps:0,dpm:maps?d/maps:0}}
function detailRows(id){const activeIds=new Set(activeMatches().map(x=>x.match_id));return DB.maps.filter(m=>m.archived!==true&&activeIds.has(m.match_id)&&m.stats_available).flatMap(m=>{const s=m.player_stats.find(x=>x.player_id===id);return s?[{...s,map:m.map,map_id:m.map_id,match_id:m.match_id,score:m.score}]:[]})}
function stability(id,rows=detailRows(id),fullPool=true,totalOverride=null){const detailed=rows.length;if(!detailed)return{score:0,plus:0,total:totalOverride??(fullPool?playedMapsFor(id):0),detailed:0};const total=totalOverride??(fullPool?playedMapsFor(id) :detailed);const rate=t=>rows.filter(r=>r.deaths>0&&r.kills/r.deaths>=t).length/Math.max(1,total);return{score:100*(.4*rate(1)+.3*rate(1.5)+.2*rate(2)+.1*rate(3)),plus:rows.filter(r=>r.kills>=r.deaths).length,total,detailed}}
function form(id,rows=detailRows(id)){if(!rows.length)return{form:null,trend:null,n:0};const n=Math.min(10,rows.length),last=rows.slice(-n),first=rows.slice(0,n);const av=r=>r.reduce((z,x)=>z+x.kills-x.deaths,0)/r.length;return{form:av(last),trend:av(last)-av(first),n}}
function rangeStats(id,rows=detailRows(id)){if(!rows.length)return{low:null,avg:null,high:null,spread:null};const vals=rows.map(r=>r.kills-r.deaths),low=Math.min(...vals),high=Math.max(...vals),avg=vals.reduce((a,b)=>a+b,0)/vals.length;return{low,avg,high,spread:high-low}}
function impact(id,rows=detailRows(id),includeCompact=true){const x=aggregate(id,rows,includeCompact);return x.maps?clamp(50+5*((x.kdDiff/x.maps)+.5*x.apm),0,100):0}
function index(id,rows=detailRows(id),includeCompact=true){const x=aggregate(id,rows,includeCompact),st=stability(id,rows,true),fo=form(id,rows);const kdScore=clamp((x.kd-.5)*100,0,100),diffScore=clamp(((x.kdDiff/Math.max(1,x.maps))+5)/10*100,0,100),vol=clamp((x.kpm-10)*10,0,100),formScore=fo.form==null?0:clamp((fo.form+5)/10*100,0,100);return .35*kdScore+.25*diffScore+.15*impact(id,rows,includeCompact)+.10*st.score+.10*vol+.05*formScore}
function indexBreakdown(id,rows=detailRows(id),includeCompact=true,localStability=false){const x=aggregate(id,rows,includeCompact),st=stability(id,rows,!localStability),fo=form(id,rows),kdScore=clamp((x.kd-.5)*100,0,100),diffScore=clamp(((x.kdDiff/Math.max(1,x.maps))+5)/10*100,0,100),vol=clamp((x.kpm-10)*10,0,100),formScore=fo.form==null?0:clamp((fo.form+5)/10*100,0,100),imp=impact(id,rows,includeCompact),total=.35*kdScore+.25*diffScore+.15*imp+.10*st.score+.10*vol+.05*formScore;return{total,kdScore,diffScore,impact:imp,stability:st.score,volume:vol,formScore,kd:x.kd,diff:x.kdDiff,kpm:x.kpm,form:fo.form,trend:fo.trend,maps:x.maps}}
function eraRows(id){const rows=detailRows(id),out=[];for(let i=0;i<rows.length;i+=10){const rr=rows.slice(i,i+10),b=indexBreakdown(id,rr,false,true),a=aggregate(id,rr,false);out.push({from:i+1,to:i+rr.length,maps:rr.length,kd:a.kd,diff:a.kdDiff,idx:b.total})}return out}
function indexReasons(id){const rows=detailRows(id),b=indexBreakdown(id,rows,true),last=rows.at(-1),prev=rows.length>1?rows.slice(0,-1):rows,prevB=indexBreakdown(id,prev,true);if(!last)return[];const careerKD=b.kd, lastKD=last.deaths?last.kills/last.deaths:0, lastDiff=last.kills-last.deaths, avgDiff=rows.reduce((z,r)=>z+r.kills-r.deaths,0)/Math.max(1,rows.length),reasons=[];reasons.push(`${lastKD>=careerKD?'✓':'✕'} K/D последней подробных карты: ${fmt(lastKD)} · карьерный ${fmt(careerKD)}`);reasons.push(`${lastDiff>=avgDiff?'✓':'✕'} K-D последней карты: ${lastDiff>0?'+':''}${lastDiff} · средний ${avgDiff>0?'+':''}${fmt(avgDiff,1)}`);reasons.push(`${b.impact>=prevB.impact?'✓':'✕'} Импакт ${fmt(b.impact,1)} · до последней карты ${fmt(prevB.impact,1)}`);reasons.push(`${b.formScore>=prevB.formScore?'✓':'✕'} Форма ${fmt(b.form,1)} · тренд ${b.trend>=0?'+':''}${fmt(b.trend,1)}`);reasons.push(`${b.stability>=prevB.stability?'✓':'✕'} Стабильность ${fmt(b.stability,1)} · до последней карты ${fmt(prevB.stability,1)}`);return reasons}
function openWhyIndex(id){const p=player(id),b=indexBreakdown(id),rr=detailRows(id),before=rr.length>1?index(id,rr.slice(0,-1)):b.total,delta=b.total-before,weights=[['Результативность · K/D',b.kdScore,.35],['K-D / карта',b.diffScore,.25],['Импакт',b.impact,.15],['Стабильность',b.stability,.10],['Объём · K/карта',b.volume,.10],['Форма',b.formScore,.05]],reasons=indexReasons(id);document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="whyIndexModal"><div class="modal panel wide"><div class="modal-head"><div><div class="eyebrow">ПРОЗРАЧНАЯ МАТЕМАТИКА</div><h2>ПОЧЕМУ ${fmt(b.total,1)}?</h2><div class="muted">${esc(p?.display_name||id)} · формула текущего Индекс игрока</div></div><button class="close" onclick="$('#whyIndexModal')?.remove()">×</button></div><div class="why-grid">${weights.map(w=>`<div class="why-row"><div><b>${w[0]}</b><span>${Math.round(w[2]*100)}% веса</span></div><strong>${fmt(w[1],1)}</strong><em>+${fmt(w[1]*w[2],1)}</em></div>`).join('')}</div><div class="mini-stats"><div class="mini-stat"><span>ИТОГ</span><strong>${fmt(b.total,1)}</strong></div><div class="mini-stat"><span>КАРТЫ</span><strong>${b.maps}</strong></div><div class="mini-stat"><span>K/D</span><strong>${fmt(b.kd)}</strong></div><div class="mini-stat"><span>K-D</span><strong>${b.diff>0?'+':''}${fmt(b.diff,1)}</strong></div><div class="mini-stat"><span>ИЗМЕНЕНИЕ</span><strong class="${delta>=0?'positive':'negative'}">${delta>0?'+':''}${fmt(delta,1)}</strong></div></div><section class="section"><div class="section-head"><h3>ПОСЛЕДНЕЕ ИЗМЕНЕНИЕ</h3><span class="muted">автоматически из базы</span></div>${reasons.map(x=>`<div class="reason-row">${esc(x)}</div>`).join('')}</section><div class="notice">Формула прозрачна: 35% K/D · 25% K-D/карта · 15% Импакт · 10% Стабильность · 10% K/карта · 5% Форма. Никаких скрытых показателей.</div></div></div>`)}

function mapStats(mapName){const ms=DB.maps.filter(m=>m.archived!==true&&m.map===mapName&&m.stats_available);let k=0,d=0,a=0,rows=0;for(const m of ms)for(const s of m.player_stats)if(s.player_id){k+=s.kills;d+=s.deaths;a+=s.assists;rows++}return{maps:DB.maps.filter(m=>m.archived!==true&&m.map===mapName).length,detailed:ms.length,k,d,a,kd:d?k/d:0,diff:k-d,rows}}
function record(metric,dir='max'){const arr=[];for(const p of activePlayers())for(const r of detailRows(p.player_id))arr.push({p:p.display_name,r,val:metric==='kills'?r.kills:metric==='kd'?(r.deaths?r.kills/r.deaths:0):r.kills-r.deaths});arr.sort((a,b)=>dir==='max'?b.val-a.val:a.val-b.val);return arr[0]}
function nav(){const items=[['home','⌂','ГЛАВНАЯ'],['analytics','▥','БАЗА'],['base','▤','МАТЧИ'],['maps','◫','КАРТЫ'],['teams','♟','СОСТАВЫ'],['records','♜','РЕКОРДЫ']];const sub={analytics:[['players','Игроки'],['compare','Сравнение игроков'],['homeMetric','Графики накопления'],['profile','Форма / стабильность']],maps:[['maps','Лаборатория карт'],['mapdna','ДНК карты']],teams:[['teams','Создать состав'],['teams','Подбор игроков / Что если']]};$('#nav').innerHTML=items.map(([id,ico,n])=>{const active=state.tab===id||(['players','compare','profile'].includes(state.tab)&&id==='analytics');const menu=sub[id];return `<div class="nav-group ${menu?'has-menu':''}"><button class="nav-btn ${active?'active':''}" data-tab="${id}"><span class="nav-icon">${ico}</span><span>${n}</span>${menu?'<span class="nav-caret">⌄</span>':''}</button>${menu?`<div class="nav-menu">${menu.map(([target,label])=>`<button data-sub="${target}" data-parent="${id}">${label}</button>`).join('')}</div>`:''}</div>`}).join('');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});document.querySelectorAll('[data-sub]').forEach(b=>b.onclick=()=>{const t=b.dataset.sub;if(b.dataset.parent==='analytics'&&t==='compare')state.tab='compare';else if(b.dataset.parent==='analytics'&&t==='players')state.tab='analytics';else if(b.dataset.parent==='analytics'&&t==='profile')state.tab='analytics';else if(b.dataset.parent==='analytics'&&t==='homeMetric')state.tab='home';else if(b.dataset.parent==='maps')state.tab='maps';else if(b.dataset.parent==='teams')state.tab='teams';render()});$('#settingsBtn').onclick=()=>{state.tab='settings';render()}}
